// Optional claims that reach the visibility gate (PRO-015 criterion 1; 05 §3.1, §5.5; 08 §9):
// a token's `access_since` is read into the identity, the room connection carries it, and the
// `since_access` gate uses that time. Every key here is generated by the test.
import { randomUUID } from 'node:crypto';
import { EMPTY_PERMISSIONS, type HistoryVisibility } from '@docedit/authority';
import { uuid7 } from '@docedit/model';
import { cdmSchema } from '@docedit/model/prosemirror';
import { beforeEach, describe, expect, it } from 'vitest';
import { signJws } from '../../src/control-plane/jwt.ts';
import { MemoryTenantRegistry } from '../../src/control-plane/tenants.ts';
import { signingKey, TokenService } from '../../src/control-plane/tokens.ts';
import { MemoryUserDirectory } from '../../src/control-plane/users.ts';
import { gateOf, type StoredState } from '../../src/data-plane/gate.ts';
import { connectionOf } from '../../src/data-plane/room-host.ts';
import { hostKey } from './support.ts';

const SERVICE = 'https://docs.example.test';
const schema = cdmSchema();

/** A one-paragraph document: the gate reads regions only, so this is enough (as gate.test.ts). */
const head = schema.nodeFromJSON({
  type: 'doc',
  content: [
    {
      type: 'defs',
      content: [
        {
          type: 'settings',
          attrs: { lang: 'en-GB', defaultTabStop: 720, defaultParagraphStyle: 'Normal' },
        },
        {
          type: 'style_def',
          attrs: { id: 'Normal', kind: 'paragraph', name: 'Normal', builtIn: true },
        },
        {
          type: 'page_setup',
          attrs: {
            id: 'ps1',
            width: 11906,
            height: 16838,
            marginTop: 1440,
            marginRight: 1440,
            marginBottom: 1440,
            marginLeft: 1440,
          },
        },
      ],
    },
    {
      type: 'body',
      attrs: { pageSetup: 'ps1' },
      content: [{ type: 'paragraph', attrs: { id: 'p0000000000000001', style: 'Normal' } }],
    },
  ],
});

/** A log of `n` commits, the commit `seq` made at `seq * 1000` milliseconds (as gate.test.ts). */
function stored(setting: HistoryVisibility, n: number): StoredState {
  return {
    setting,
    head,
    headSeq: n,
    perms: EMPTY_PERMISSIONS,
    log: Array.from({ length: n }, (_, i) => ({ seq: i + 1, time: (i + 1) * 1000 })),
    now: 10_000_000,
  };
}

describe('access_since reaches the since_access gate (PRO-015 criterion 1)', () => {
  let now = Date.now();
  let tenant: string;
  let registry: MemoryTenantRegistry;
  let tokens: TokenService;
  const host = hostKey('ES256');
  const doc = uuid7();

  beforeEach(async () => {
    now = Date.now();
    tenant = randomUUID();
    registry = new MemoryTenantRegistry(() => now);
    await registry.putTenant(tenant, 't');
    await registry.addKey(tenant, { kid: host.kid, use: 'user', alg: 'ES256', jwk: host.jwk });
    tokens = new TokenService({
      registry,
      users: new MemoryUserDirectory(),
      serviceId: SERVICE,
      signing: signingKey(undefined, 'svc'),
      now: () => now,
    });
  });

  const sign = (claims: Record<string, unknown> = {}) => {
    const iat = Math.floor(now / 1000);
    return signJws(
      { alg: host.alg, typ: 'JWT', kid: host.kid },
      {
        iss: 'host',
        aud: SERVICE,
        iat,
        exp: iat + 300,
        jti: uuid7(),
        tid: tenant,
        sub: 'reader-1',
        docs: { [doc]: 'viewer' },
        ...claims,
      },
      host.privateKey,
    );
  };

  it('reads access_since (RFC 3339) into the identity as Unix milliseconds', async () => {
    const id = await tokens.verifyUser(sign({ access_since: new Date(2500).toISOString() }));
    expect(id.accessSince).toBe(2500);
  });

  it('gives the room connection the access time, and the gate shows the state current at that time', async () => {
    const id = await tokens.verifyUser(sign({ access_since: new Date(2500).toISOString() }));
    // Commits at 1,000 to 5,000 ms: the last commit at or before 2,500 ms is seq 2.
    expect(gateOf(connectionOf(id, 'viewer'), stored('since_access', 5))).toBe(2);
  });

  it('fails closed to the head when the token carries no access_since', async () => {
    const id = await tokens.verifyUser(sign());
    expect(id.accessSince).toBeUndefined();
    expect(gateOf(connectionOf(id, 'viewer'), stored('since_access', 5))).toBe(5);
  });
});
